-- Dumping data for table `holidaydescriptions_dbc`
--

LOCK TABLES `holidaydescriptions_dbc` WRITE;
/*!40000 ALTER TABLE `holidaydescriptions_dbc` DISABLE KEYS */;
INSERT INTO `holidaydescriptions_dbc` VALUES (1,'The Darkmoon Faire is here, this time in idyllic Elwynn Forest.\n\nMeet Silas Darkmoon and his troupe, play games that test mind and nerve, and behold exotic sights from the four corners of Azeroth... and beyond!'),(2,'Azeroth celebrates!  Each racial capital holds fireworks shows every hour, all night long!'),(4,'A fishing tournament, competed along the coasts of Stranglethorn Vale.  Catch as many tastyfish as you can!  \n\nWill you be the master fisherman who catches forty fish first and wins the grand prize?'),(8,'First celebrated by the dwarves, Brewfest now holds appeal among all the races of Azeroth!\n\nVisit the Alliance camp outside Ironforge, or the Horde camp outside Orgrimmar, and join the party!'),(9,'Something is in the air in the major cities of Azeroth.  Many guards and townsfolk spend their days giving and receiving gifts to other amorous citizens.'),(10,'A time of merriment and celebration, dedicated to the hottest season of the year.'),(11,'After the sun sets, the end of Midsummer is celebrated, with an hourly firework extravaganza.\n\nTo watch the show, visit any capital city or Booty Bay.'),(12,'Show an orphan what the hero\'s life is like!  Visit Orphan Matron Nightingale in Stormwind, Orphan Matron Battlewail in Orgrimmar, Orphan Matron Mercy in Shattrath, or Orphan Matron Aria in Dalaran and make a child\'s dream come true.'),(13,'Greatfather Winter is visiting the cities of Ironforge and Orgrimmar, courtesy of Smokywood Pastures.  And throughout Azeroth, it is the season to be jolly!'),(14,'The feast of Noblegarden has arrived.  The proving grounds of each race, the place where young heroes first test their strength, each holds cleverly hidden treasure eggs.  How many can you find?'),(15,'Hallow\'s End celebrates the break of the Forsaken from the Scourge.\n\nFun and mischief reign as the Innkeepers of Azeroth give treats, and tricks, to whomever asks.'),(16,'The Harvest Festival is a time to commemorate those  who have sacrificed their lives to help friends and allies.  Feasts are held outside Orgrimmar and Ironforge in honor of these fallen heroes.'),(17,'Every year the druids of Moonglade hold a celebration of their city\'s great triumph over an ancient evil. During the Lunar Festival, citizens of Azeroth have the opportunity to honor their elders by celebrating their sage wisdom, sharing in magnificent feasts, and of course... shooting fireworks!\n'),(18,'Started by the dwarves, Brewfest is now a worldwide celebration of brews and good times.'),(21,'Captain Demeza sails to the goblin town of Booty Bay and recruits land-lovers into her buccaneer ranks.\n\nVisit her or her henchmen in the capital cities if the pirate\'s life is for you!'),(22,'The battle for Alterac Valley grows intense.  Greater honor is given to those who pledge sword to their liege and battle in Alterac.'),(23,'The battle for Arathi Basin grows intense.  Greater honor is given to those who pledge sword to their liege and battle in Arathi.'),(24,'The battle for the Eye of the Storm grows intense.  Greater honor is given to those who pledge sword to their liege and battle in the Eye.'),(25,'The battle for Warsong Gulch grows intense.  Greater honor is given to those who pledge sword to their liege and battle in the Gulch.'),(26,'The Darkmoon Faire is here, this time at the foot of Thunder Bluff.\n\nMeet Silas Darkmoon and his troupe, play games that test mind and nerve, and behold exotic sights from the four corners of Azeroth... and beyond!'),(27,'The Darkmoon Faire is here, this time outside Shattrath City.\n\nMeet Silas Darkmoon and his troupe, play games that test mind and nerve, and behold exotic sights from the four corners of Azeroth... and beyond!'),(41,'The battle for the Strand of the Ancients grows intense.  Greater honor is given to those who pledge sword to their liege and battle upon the Strand.'),(61,'The Wrath of the Lich King launches on November 13th.\n\nAlliance ships depart from Stormwind and Menethil Harbor.\n\nHorde Zeppelins leave from outside Orgrimmar and Undercity.\n\nSee you in Northrend...'),(81,'During the Day of the Dead, people gather in graveyards to celebrate with and cherish the spirits of those they have lost.\n\nOne can find the festivities in the cemeteries of any major city, where celebrants cook, dance, don costumes, and more.'),(101,'Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.'),(121,'The battle for the Isle of Conquest grows intense.  Greater honor is given to those who pledge sword to their liege and battle upon the Isle.'),(141,'Test test'),(161,'The Kalu\'ak hold a fishing derby every few days in Northrend.  Be the first to catch a Blacktip Shark and win respect with the Kalu\'ak, and an amazing prize!');
/*!40000 ALTER TABLE `holidaydescriptions_dbc` ENABLE KEYS */;
UNLOCK TABLES;

