INSERT INTO `holidaynames_dbc` VALUES (1,'Darkmoon Faire'),(5,'Fireworks Celebration'),(6,'Stranglethorn Fishing Extravaganza'),(7,'Brewfest'),(9,'Love is in the Air'),(11,'Midsummer Fire Festival'),(12,'Fireworks Spectacular'),(13,'Children\'s Week'),(14,'Feast of Winter Veil'),(15,'Noblegarden'),(16,'Hallow\'s End'),(17,'Harvest Festival'),(18,'Lunar Festival'),(19,'Brewfest'),(21,'Pirates\' Day'),(22,'Call to Arms: Alterac Valley'),(23,'Call to Arms: Arathi Basin'),(24,'Call to Arms: Eye of the Storm'),(25,'Call to Arms: Warsong Gulch'),(41,'Call to Arms: Strand of the Ancients'),(61,'Wrath of the Lich King Launch'),(81,'Day of the Dead'),(101,'Pilgrim\'s Bounty'),(121,'Call to Arms: Isle of Conquest'),(141,'Mohawk Promotion'),(161,'Kalu\'ak Fishing Derby');
