INSERT INTO `server_news` VALUES (1,'Welcome to your realm site','welcome-to-your-realm-site','This is sample news content. Edit or replace it under Admin → News. Use news posts for patch notes, events, and maintenance windows.','Staff','2026-01-01 12:00:00','img/newsimg/news1.jpg',1,'update'),(2,'Wrath of the Lich King (3.3.5a)','wotlk-335-client','Players need a World of Warcraft 3.3.5a client. Update the Downloads page with your realmlist and client links before going live.','Staff','2026-01-02 12:00:00','img/newsimg/news2.jpg',0,'update'),(3,'Realm Shop and milestone tokens','realm-shop-milestone-tokens','The sample shop catalog and achievement rewards are pre-configured. Achievement and character-stat rewards grant website tokens when players log in. Adjust prices and criteria in Admin → Shop → Rewards.','Staff','2026-01-03 12:00:00','img/newsimg/news3.jpg',0,'other');
